from pathlib import Path
p=Path('playtest/index.html')
s=p.read_text()
s=s.replace('0.19.5-r7-storypass','0.20.0-narrative-flow').replace("version:'0.19.5-r7'","version:'0.20.0'").replace("BUILD_SCHEMA='0195-r7'","BUILD_SCHEMA='0200'")
intro=r'''<script id="v020-chapter1-intro">(()=>{const K='eldoria-v020-ch1-intro',OLD='eldoria-aldric-story-r7-v3';function markOld(){try{const o=JSON.parse(localStorage.getItem(OLD)||'{}');o['chapter1-start']=1;localStorage.setItem(OLD,JSON.stringify(o))}catch{}}function chapterOneReady(){const t=document.body.innerText||'';return /Las Cenizas de Valoria|Levanta de nuevo lo esencial|Granero|Reconstru/i.test(t)}function start(force=false){if((!force&&!chapterOneReady())||localStorage.getItem(K)||document.querySelector('.aldric-cinematic'))return;markOld();localStorage.setItem(K,'1');const full='Mi señor, Valoria sobrevivió… pero apenas.\n\nNuestros almacenes están vacíos, los talleres destruidos y los soldados dispersos. Antes de buscar respuestas sobre la Brecha, debemos conseguir que el reino vuelva a sostenerse.\n\nEmpecemos por el Granero. Sin alimento, Valoria no puede levantarse.';const o=document.createElement('div');o.className='aldric-cinematic';o.dataset.scene='chapter1-intro-v020';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.innerHTML='<div class="aldric-dialogue"><div class="aldric-head"><div class="aldric-portrait">⚔</div><div><div class="aldric-name">SIR ALDRIC</div><div class="aldric-role">Guardián de Valoria</div></div></div><div class="aldric-copy"><div class="aldric-ghost"></div><div class="aldric-typed"></div></div><div class="aldric-wait">ESCUCHA…</div><button class="aldric-continue primary" type="button">Continuar</button></div>';document.body.appendChild(o);document.documentElement.style.overflow='hidden';const b=o.querySelector('.aldric-dialogue'),g=o.querySelector('.aldric-ghost'),t=o.querySelector('.aldric-typed'),btn=o.querySelector('button');g.textContent=full;let i=0;(function type(){if(i<full.length){t.textContent=full.slice(0,++i);setTimeout(type,22)}else{b.classList.add('done');btn.focus()}})();btn.onclick=()=>{if(!b.classList.contains('done'))return;o.remove();document.documentElement.style.overflow='';[...document.querySelectorAll('button,[role=button],.building')].find(e=>/granero/i.test(e.innerText||e.textContent||''))?.classList.add('v020-focus')}}function bindReset(){document.addEventListener('click',e=>{const el=e.target?.closest?.('button,[role=button],a');if(!el)return;const t=(el.innerText||el.textContent||'').trim();if(/partida nueva|nueva partida|reiniciar.*partida|borrar.*progreso/i.test(t)){localStorage.removeItem(K);localStorage.removeItem(OLD);setTimeout(()=>start(true),700)}},true)}bindReset();setTimeout(start,650);let q;new MutationObserver(()=>{clearTimeout(q);q=setTimeout(()=>start(false),120)}).observe(document.documentElement,{subtree:true,childList:true,characterData:true})})();</script>'''
if 'v020-chapter1-intro' not in s:s=s.replace('</body>',intro+'</body>')
p.write_text(s)
print('Restored v0.20 narrative layer with reliable Chapter I Aldric trigger')
